            if (take > remaining / cost)
                take = remaining / cost;
            if (take == 0)
                break;
            algorithm->update(state->context, trap->current.data + trap->offset, take);
            trap->offset += take;
            remaining -= take * cost;
            if (trap->offset != trap->current.size)
                break;
